def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n < 8:
        cons_opp_d = 0
        for o in reversed(opp):
            if o == 'D':
                cons_opp_d += 1
            else:
                break
        cons_me_d = 0
        for m in reversed(me):
            if m == 'D':
                cons_me_d += 1
            else:
                break
        if cons_opp_d >= 4 and cons_me_d >= 4:
            return 'C'
        if cons_opp_d >= 2:
            return 'D'
        return 'C'

    W_rate = min(8, n)
    opp_c_rate = sum(1 for i in range(n - W_rate, n) if opp[i] == 'C') / W_rate

    W_cond = min(20, n)
    cC = cD = dC = dD = 0
    for i in range(n - W_cond, n - 1):
        if me[i] == 'C':
            if opp[i+1] == 'C':
                cC += 1
            else:
                cD += 1
        else:
            if opp[i+1] == 'C':
                dC += 1
            else:
                dD += 1

    pC = (cC + 1) / (cC + cD + 2)
    pD = (dC + 1) / (dC + dD + 2)

    cons_opp_d = 0
    for o in reversed(opp):
        if o == 'D':
            cons_opp_d += 1
        else:
            break
    cons_me_d = 0
    for m in reversed(me):
        if m == 'D':
            cons_me_d += 1
        else:
            break

    if cons_opp_d >= 4 and cons_me_d >= 4:
        return 'C'

    if opp_c_rate < 0.25:
        return 'D'

    if opp_c_rate > 0.75:
        if pD > 0.6:
            return 'D'
        if n >= 6:
            last3_me = me[-3:]
            last3_opp = opp[-3:]
            if all(m == 'C' for m in last3_me) and all(o == 'C' for o in last3_opp):
                if rng.random() < 0.15:
                    return 'D'
        return 'C'

    if pC > 0.65 and pD < 0.35:
        return 'C'

    if pC < 0.35 and pD < 0.35:
        return 'D'
    if abs(pC - pD) < 0.2:
        return 'D'

    if opp[-1] == 'C':
        return 'C'
    else:
        if cons_opp_d >= 3 and me[-1] == 'D':
            return 'C'
        return 'D'
